#include <iostream>
#include <print>
#include <string>
#include <utility>
#include <vector>

class Line {
public:
    Line(std::string item, long long price, int quantity)
        : item_(std::move(item)), price_(price), quantity_(quantity) {}

    long long cost() const {
        return price_ * quantity_;
    }

    const std::string &item() const {
        return item_;
    }

private:
    std::string item_;
    long long price_;
    int quantity_;
};

class Order {
public:
    void add(Line line) {
        lines_.push_back(std::move(line));
    }

    long long total() const {
        long long sum = 0;
        for (const Line &line : lines_) {
            sum += line.cost();
        }
        return sum;
    }

    std::size_t size() const {
        return lines_.size();
    }

private:
    std::vector<Line> lines_;
};

int main() {
    Order order;
    std::string item;
    long long price;
    int quantity;
    while (std::cin >> item >> price >> quantity) {
        Line line(item, price, quantity);
        std::println("{}: {}", line.item(), line.cost());
        order.add(std::move(line));
    }
    std::println("позиций {}, итого {}", order.size(), order.total());
    return 0;
}

