#include <iostream>
#include <print>
#include <string>
#include <vector>

class Playlist {
public:
    void add(const std::string &song) {
        songs_.push_back(song);
    }

    void next() {
        if (!songs_.empty()) {
            current_ = (current_ + 1) % songs_.size();
        }
    }

    void prev() {
        if (!songs_.empty()) {
            current_ = (current_ + songs_.size() - 1) % songs_.size();
        }
    }

    const std::string *current() const {
        return songs_.empty() ? nullptr : &songs_[current_];
    }

private:
    std::vector<std::string> songs_;
    std::size_t current_ = 0;
};

class Player {
public:
    void add(const std::string &song) {
        list_.add(song);
    }

    void next() {
        list_.next();
    }

    void prev() {
        list_.prev();
    }

    void play() const {
        if (const std::string *song = list_.current()) {
            std::println("играет: {}", *song);
        } else {
            std::println("плейлист пуст");
        }
    }

private:
    Playlist list_;
};

int main() {
    Player player;
    std::string command;
    while (std::cin >> command) {
        if (command == "add") {
            std::string song;
            std::cin >> song;
            player.add(song);
        } else if (command == "next") {
            player.next();
        } else if (command == "prev") {
            player.prev();
        } else {
            player.play();
        }
    }
    return 0;
}

